-- 202609010001a — 운영진만 읽는 분석 문서를 DB 에 둔다
--
-- Supabase SQL Editor 에 붙여넣어 실행한다. 여러 번 실행해도 같다.
--
-- ── 왜 DB 인가 ────────────────────────────────────────────
-- 이 문서에는 회원이 직접 쓴 자유서술 원문이 들어 있다. 공개하면 안 된다.
-- 그런데 **번들은 공개다** — 화면 코드에 본문을 넣으면 암호는 가림막일 뿐이고,
-- 배포된 assets/index-*.js 를 내려받아 그냥 읽을 수 있다.
-- (2026-08-29 에 실제로 받아서 확인했다.)
--
-- 그래서 본문을 표에 두고 **정책을 하나도 만들지 않는다.**
-- 정책 없는 표는 RLS 아래서 아무도 못 읽는다 — survey_responses 와 같은 방식이다.
-- 읽는 길은 암호를 먼저 검사하는 security definer 함수 하나뿐이다.
--
-- ── 왜 HTML 이 아니라 블록(jsonb)인가 ─────────────────────
-- SPA 의 CSP 가 `style-src-attr 'none'` 이다. HTML 을 그대로 심으면
-- 막대 너비(style="width:83%")가 전부 막혀 **0 폭이 된다.**
-- React 가 style prop 으로 그리면 CSSOM 이라 막히지 않는다.
-- 그래서 자료만 넘기고 그리는 일은 화면(SurveyAdmin 의 Doc)이 한다.
-- 블록 종류는 app/src/lib/adminDoc.ts 의 타입과 짝이 맞아야 한다.
--
-- ── 고칠 때 ───────────────────────────────────────────────
-- 본문은 손으로 고치지 않는다. 분석을 다시 돌려 이 파일을 새로 만들고 실행한다.
-- slug 가 같으면 덮어쓴다.

begin;

create table if not exists public.admin_docs (
  slug       text primary key,
  title      text not null,
  -- 블록 배열. 화면이 종류(k)를 보고 그린다.
  body       jsonb not null,
  updated_at timestamptz not null default now()
);

alter table public.admin_docs enable row level security;

-- **정책을 만들지 않는다.** 이것이 자물쇠다.
-- grant 도 주지 않는다 — 함수(security definer)로만 닿는다.
revoke all on public.admin_docs from anon, authenticated;

comment on table public.admin_docs is
  '운영진만 읽는 문서. 정책 없이 잠가 두고 survey_admin_doc 으로만 읽는다. 자유서술 원문이 들어 있다.';


-- ── 목록 ──────────────────────────────────────────────────
create or replace function public.survey_admin_docs(p_password text)
returns table (slug text, title text, updated_at timestamptz)
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
begin
  if not public.survey_admin_ok(p_password) then
    raise exception '운영자 암호가 맞지 않습니다.' using errcode = '28000';
  end if;
  return query
    select d.slug, d.title, d.updated_at
      from public.admin_docs d
     order by d.updated_at desc;
end;
$$;

-- ── 본문 ──────────────────────────────────────────────────
create or replace function public.survey_admin_doc(p_password text, p_slug text)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  v jsonb;
begin
  if not public.survey_admin_ok(p_password) then
    raise exception '운영자 암호가 맞지 않습니다.' using errcode = '28000';
  end if;
  select jsonb_build_object('title', d.title, 'updated_at', d.updated_at, 'body', d.body)
    into v
    from public.admin_docs d
   where d.slug = p_slug;
  if v is null then
    raise exception '없는 문서입니다.' using errcode = 'P0002';
  end if;
  return v;
end;
$$;

grant execute on function public.survey_admin_docs(text)       to anon, authenticated;
grant execute on function public.survey_admin_doc(text, text)  to anon, authenticated;


-- ── 본문 넣기 ─────────────────────────────────────────────
-- 아래 한 줄이 매우 길다. 분석을 다시 돌리면 이 파일째로 새로 만든다.
