values (
  'survey-2026-08',
  '세 사람과 열 가지 규칙 — 2026년 8월 설문 (n=18)',
  '[{"k": "cover", "t": "세 사람과 열 가지 규칙", "eyebrow": "41교구 전시·박물관 동아리 · 2026년 8월 설문", "dek": "21명 중 **18명**이 답했습니다. 동아리 안에는 서로 다른 세 사람이 있고, 지금 일정은 그중 **한 명만** 만족시키고 있습니다. 돈도, 거리도, 마음도 아닙니다 — **방식**입니다.", "tiles": [["15", "토요일 낮이면 온다", "18명 중 15명 · 여기는 다툴 게 없다"], ["6", "「보고 싶은 게 다르다」", "「어려움 없음」과 공동 1위"], ["9 : 4", "식사를 원하는 사람", "자주 오는 9명 전원 : 그 밖 4명"], ["3", "아직 말이 없다", "지난달 5명에서 둘이 답했다"]]}, {"k": "h", "n": "01", "t": "지난 가이드 뒤로 달라진 것"}, {"k": "lede", "t": "8월 29일 가이드는 **16명**으로 썼습니다. 그 뒤 두 분이 더 답해 **18명**이 됐습니다. 그리고 그 두 분이 지난 가이드의 **예측을 시험**해 줬습니다."}, {"k": "card", "t": "말 없는 사람이 5명에서 3명으로", "ps": ["운영규정 동의 공지(마감 8월 31일)를 올린 뒤 **8월 31일에 한 명, 9월 1일에 한 명**이 답했습니다. 지난 가이드가 「이번 주에 할 것」 첫 줄로 적었던 **「아직 답 안 한 분들에게 따로 연락하기」**가 실제로 두 명을 데려온 것입니다.", "이 설문은 **공지할 때마다 사람이 왔습니다** — 첫날 8명, 마감 전 재공지에 6명, 규정 동의 공지에 2명. 한 번 올리고 끝냈다면 절반을 놓쳤을 것입니다."]}, {"k": "card", "t": "예측은 절반 맞았습니다", "ps": ["지난 가이드는 **「아직 안 답한 분들은 아쉬운 점이 더 많을 수 있다」**고 적었습니다. 새로 답한 두 분은 정반대였습니다."]}, {"k": "table", "head": ["새로 답한 분", "참여", "고른 장벽"], "rows": [["8/31", "2회 이상 참여", "특별한 어려움 없음"], ["9/1", "온라인만 보고 있음", "**비용이 부담됨 · 단체방에서 먼저 말하기 부담 · 개인 사정** (셋)"]]}, {"k": "p", "t": "한 분은 아무 불편이 없는 활동 회원이었고, 한 분은 **정확히 걱정하던 그 사람**이었습니다 — 온라인으로만 보고 있고, 돈이 부담되고, 단톡방에서 먼저 말하기 어려운. **남은 3명 중에도 이런 분이 있을 수 있습니다.**"}, {"k": "note", "t": "한 분은 자유서술에 「생각해볼게요」라고만 적었습니다. **아직 마음을 안 정한 것이지, 떠난 것이 아닙니다.**"}, {"k": "card", "t": "지난 가이드의 규칙 하나는 이제 못 씁니다", "ps": ["지난 가이드의 **규칙 05 「이름을 안 써도 되는 선택지를 계속 둔다」**는 「이름 안 쓴 7명 중에 어색하다는 4명이 전부 있다」는 관찰에 기댄 것이었습니다. **지금은 이름 칸이 19건 모두 비어 있습니다.** 8월 28일에는 값이 있었으니 그 뒤 지워진 것으로 보입니다.", "결론(이름은 선택으로 두자)은 그대로 두어도 되지만, **이번 자료로는 그 근거를 다시 확인할 수 없습니다.** 아래 규칙 05를 바꿔 적었습니다."]}, {"k": "h", "n": "02", "t": "동아리 안의 세 사람"}, {"k": "lede", "t": "숫자를 사람으로 바꾸면 무엇을 놓치고 있는지 바로 보입니다. 셋이 원하는 게 서로 다른데, 지금 일정은 그중 **한 명**에게 맞춰져 있습니다."}, {"k": "person", "tone": "a", "t": "자주 오는 사람", "cnt": "9명 · 2회 이상", "dek": "이미 오는 분들입니다. 작품 앞에 오래 서 있고, 날짜가 바뀌어도 따라옵니다.", "pts": [["9/9", "**관람 뒤 식사를 원한다** — 한 명도 빠짐없이"], ["6/9", "날짜를 그때그때 맞출 수 있다 (그 밖은 2/9)"], ["6/9", "작가·작품 이야기를 미리 알고 싶다 (그 밖은 3/9)"], ["5/9", "문화 탐방·여행을 좋아한다 (그 밖은 1/9)"]], "careful": "이분들 취향에 맞추면 일정이 굳습니다. 지금 미술·전시 위주로 짜인 것이 딱 그 상태입니다."}, {"k": "person", "tone": "b", "t": "한두 번 온 사람", "cnt": "9명 · 1회 이하", "dek": "한 번 오고 멈춘 분들입니다. 나가는 문 쪽에 서 있지만 아직 돌아보고 있습니다.", "pts": [["8/9", "「날짜를 한눈에」만 알려 달라 — 작가 이야기는 3/9"], ["7/9", "**토요일 저녁에 올 수 있다** (자주 오는 사람은 2/9)"], ["5/9", "음악회·공연을 좋아한다 · 영화는 4/9 (자주 오는 사람은 1/9)"], ["5/9", "「좋은 일정 있을 때만」 — 매달 나온다고 약속하지 않는다"], ["5/9", "그런데 **「보고 싶은 곳 제안」은 하겠다** (자주 오는 사람보다 많다)"]], "careful": "4명이 「지금은 역할을 맡기 어렵다」고 했습니다. **못 나오는 것과 관심이 없는 것은 다릅니다.** 같은 사람들이 제안은 하겠다고 합니다."}, {"k": "person", "tone": "c", "t": "말 없는 사람", "cnt": "3명 · 아직 안 답함", "dek": "21명 중 3명이 아직 답하지 않았습니다. 이분들에 대해 아는 것이 없습니다.", "pts": [["3/21", "일곱 명 중 한 명이 통째로 빠져 있다"], ["단서", "지난달 이 자리에 있던 두 분이 답했고, **그중 한 분이 장벽을 셋 골랐습니다** — 비용·말 꺼내기 부담·개인 사정"]], "careful": "남은 3명도 아쉬운 점이 많을 수 있습니다. 이대로 결론을 내면 실제보다 **좋아 보이게** 됩니다. 「특별한 어려움 없음」 33%도 마찬가지입니다."}, {"k": "h", "n": "03", "t": "두 사람이 크게 다른 여섯 가지"}, {"k": "lede", "t": "두 집단의 답이 가장 많이 벌어진 것들입니다. **한쪽에 맞추면 다른 쪽을 잃는다**는 뜻입니다. 지난 가이드의 네 가지가 **18명에서도 그대로**였고, 둘이 새로 붙었습니다. 초록은 자주 오는 사람 9명, 보라는 한두 번 온 사람 9명입니다."}, {"k": "gap", "t": "관람 뒤 **식사**를 함께하고 싶다", "mult": "2.2배", "side": "a", "a": [9, 9, 100], "b": [4, 9, 44], "note": "**새로 나온 것.** 이 데이터에서 100%가 나온 유일한 항목입니다. 카페·티타임은 양쪽 다 7/9로 **똑같습니다** — 차이는 오직 식사에서 납니다."}, {"k": "gap", "t": "문화 탐방·여행을 좋아한다", "mult": "5.0배", "side": "a", "a": [5, 9, 56], "b": [1, 9, 11], "note": null}, {"k": "gap", "t": "영화를 좋아한다", "mult": "4.0배", "side": "b", "a": [1, 9, 11], "b": [4, 9, 44], "note": "음악회·공연도 같은 방향입니다 — 3/9 대 5/9."}, {"k": "gap", "t": "「지금은 역할을 맡기 어렵다」", "mult": "4.0배", "side": "b", "a": [1, 9, 11], "b": [4, 9, 44], "note": "**새로 나온 것.** 그런데 같은 집단의 5/9가 「보고 싶은 곳 제안」은 하겠다고 했습니다 — 자주 오는 사람(4/9)보다 **많습니다.** 몸으로 오는 것과 의견을 내는 것은 다른 문제입니다."}, {"k": "gap", "t": "토요일 저녁에 올 수 있다", "mult": "3.5배", "side": "b", "a": [2, 9, 22], "b": [7, 9, 78], "note": "토요일 **오후**는 양쪽 다 높습니다(7/9 대 8/9) — 정기 관람은 그대로 두면 됩니다. 벌어지는 것은 **저녁**입니다."}, {"k": "gap", "t": "날짜를 그때그때 맞출 수 있다", "mult": "3.0배", "side": "a", "a": [6, 9, 67], "b": [2, 9, 22], "note": "한두 번 온 분들은 **미리 정해 줘야** 옵니다. 갑자기 잡는 일정은 이분들에게 닿지 않습니다."}, {"k": "flag", "t": "이건 검정 결과가 아닙니다", "ps": ["한 집단이 9명이라 **한 사람이 11%p**입니다. 「어느 쪽이 많은가」라는 방향은 믿되, 몇 배인지는 대략으로만 보세요. 그래도 적는 이유는 여섯 가지 모두 **두 배 이상** 벌어졌고, 네 가지는 지난달 16명 자료에서도 같은 방향이었기 때문입니다."]}, {"k": "h", "n": "04", "t": "꼭 지킬 다섯"}, {"k": "lede", "t": "까닭이 분명하고, 돈이 안 들고, 이번 달부터 바로 할 수 있는 것만 골랐습니다."}, {"k": "rule", "kind": "yes", "n": "지킬 것 01", "t": "일정 알림은 한 사람만 올린다", "chg": null, "ps": ["한 일정에 글 하나. 바뀌면 **새 글을 쓰지 말고 그 글을 고칩니다.** 한 회원이 문제와 해법을 한 문장에 다 적어 줬습니다."], "quote": "정보를 주려는 사람이 너무 많아서 혼동됩니다. 확실하게 정해진 정보만 운영자 한 사람이 올려주길 희망합니다.", "ev": "「못 찾겠다」 4명 · 그런데 「글 양은 딱 알맞다」가 12명 — 많아서가 아니라 여럿이 올려서입니다"}, {"k": "rule", "kind": "yes", "n": "지킬 것 02", "t": "낮에 보고, 저녁 식사는 원하는 사람만", "chg": "근거 보강", "ps": ["**저녁 자리를 없애지 마세요.** 자주 오는 아홉 분은 **한 명도 빠짐없이** 식사를 원합니다. 그런데 한두 번 온 분들은 절반이 안 됩니다. **둘 다 지키는 방법은 하나뿐입니다** — 관람은 다 같이, 식사는 이어서 하고 싶은 사람만."], "quote": null, "ev": "식사 9/9 대 4/9 · 「활동마다 선택」을 고른 분이 6명(33%)"}, {"k": "rule", "kind": "yes", "n": "지킬 것 03", "t": "세 달에 한 번은 음악회나 영화로", "chg": null, "ps": ["가장 많이 나온 장벽인 **「보고 싶은 게 다르다」(6명)**의 정체가 이것입니다. 미술·전시만으로 채우면 **한두 번 온 아홉 분은 갈 자리가 없습니다.** 자리를 미리 만들어 두세요."], "quote": null, "ev": "한두 번 온 사람 — 음악회 5/9 · 영화 4/9 (자주 오는 사람은 3/9 · 1/9)"}, {"k": "rule", "kind": "yes", "n": "지킬 것 04", "t": "보는 시간을 먼저 정하고 밥은 뒤에 붙인다", "chg": null, "ps": ["묻지도 않았는데 같은 말이 **세 번** 나왔습니다. 그중 하나는 보기에 없는데도 **참여 장벽 문항에 직접 타이핑해** 넣은 것입니다.", "모이고, 옮기고, 밥 먹는 데 시간이 밀려서 보는 시간이 줄고 있습니다."], "quote": "문화를 향유하기 위한 모임인데 정작 관람 시간이 짧게 분배되는 것 같아 아쉬워요", "ev": "「공간과 분위기까지 즐기는 편」 9명(50%) · 「작품 하나를 오래」 3명"}, {"k": "rule", "kind": "yes", "n": "지킬 것 05", "t": "제안은 안 나오는 사람에게 먼저 물어본다", "chg": "새로 씀", "ps": ["지난 가이드의 이 자리는 「이름을 안 써도 되게 두자」였는데, **이름 칸이 비어 버려 그 근거를 다시 확인할 수 없습니다.** 대신 이번에 더 확실한 것이 나왔습니다.", "한두 번 온 아홉 분 중 **4명이 「지금은 역할을 맡기 어렵다」**고 했지만, **같은 집단의 5명이 「보고 싶은 곳 제안」은 하겠다**고 했습니다 — 자주 오는 분들(4명)보다 많습니다. 나오기 어려운 분에게 「제안해 주세요」는 부담이 아니라 **다른 문**입니다."], "quote": null, "ev": "제안 의향 — 한두 번 온 사람 5/9 대 자주 오는 사람 4/9 · 전체로는 9명(50%)으로 역할 1위"}, {"k": "h", "n": "05", "t": "하지 말 다섯"}, {"k": "lede", "t": "좋은 뜻으로 하기 쉬운데, 이번 설문이 거꾸로라고 말한 것들입니다."}, {"k": "rule", "kind": "no", "n": "하지 말 것 01", "t": "여러 사람이 같은 일정을 또 올리기", "chg": null, "ps": ["친절해 보이지만 거꾸로 됩니다.", "**글이 많은 게 아니라 올리는 사람이 여럿인 게 문제**입니다."], "quote": "카톡방에 글이 많아 다시 찾기가 쉽지 않고, 반복된 정보가 상이할 경우 헷갈리네요", "ev": "「메시지 양이 많다」고 한 2명은 두 분 다 「정보를 못 찾겠다」를 함께 골랐습니다"}, {"k": "rule", "kind": "no", "n": "하지 말 것 02", "t": "미술·전시로만 한 해를 채우기", "chg": null, "ps": ["동아리 이름이 「전시·박물관」이라도, **한두 번 온 아홉 분은 음악회와 영화 쪽에 있습니다.** 지금 일정은 이미 오는 분들의 취향을 한 번 더 확인해 줄 뿐입니다."], "quote": null, "ev": "문화 탐방·여행 — 자주 오는 사람 5/9 대 한두 번 온 사람 1/9 (5배)"}, {"k": "rule", "kind": "no", "n": "하지 말 것 03", "t": "열 명 넘게 통째로 몰려다니기", "chg": null, "ps": ["회원이 그대로 적었습니다.", "자주 오는 분 중에서도 이런 말이 나왔습니다 — **「친한 분들끼리 매번 모이게 되면 소외당하는 느낌이 없으면 좋겠어요. 소심한 회원을 위한 지혜를 구해봅니다.」**"], "quote": "함께 가는 인원이 10명 이상일 경우는 밥 먹는 것도 일인 거 같아요", "ev": "3~5명 작은 모임을 원한 분 3명 · 「어색하다·먼저 말하기 부담」 5명 — 그중 한 분은 2회 이상 참여자입니다"}, {"k": "rule", "kind": "no", "n": "하지 말 것 04", "t": "단톡방에서 나온 말만 듣고 정하기", "chg": null, "ps": ["단톡방에서 편하게 말할 수 있다고 한 분은 **4명뿐**입니다. 네 가지 방법 중 꼴찌입니다. **방이 조용한 건 다들 괜찮아서가 아닙니다.**"], "quote": null, "ev": "설문 13명(72%) · 운영진에게 개인적으로 9명 · 티타임 8명 · 식사 자리 8명 · 단톡방 4명"}, {"k": "rule", "kind": "no", "n": "하지 말 것 05", "t": "비용을 「문제 아님」으로 넘기기", "chg": "뒤집힘", "ps": ["지난 가이드는 「돈이 부담된다는 사람은 2명뿐이니 문제가 아니다」라고 썼습니다. **이번에 3명이 됐고, 더 중요한 것이 보입니다** — 그 세 분 중 **둘이 「무료 또는 1만원 미만」**을 적정 관람비로 골랐습니다.", "전체로 보면 비용은 고르는 기준의 꼴찌가 맞습니다(4명·22%). 하지만 **이 세 분에게는 1만원이 실제 문턱**입니다. 좋은 전시를 고르되 **무료 전시를 정기적으로 섞으면** 이분들이 빠지지 않습니다."], "quote": null, "ev": "비용 부담 3명 — 무료~1만원 2명 · 1~2만원 1명 · 9월 1일에 답한 분이 그중 하나입니다"}, {"k": "h", "n": "06", "t": "9월부터 어디로"}, {"k": "lede", "t": "회원들이 직접 적어 준 곳으로만 짰습니다. 자주 오는 사람과 한두 번 온 사람을 **번갈아** 겨냥합니다."}, {"k": "table", "head": ["언제", "누구를 위해", "어디를", "왜 여기인가"], "rows": [["9월 19일 **확정**", "모두", "《서도호》 개인전 · 국립현대미술관 서울", "이미 정해졌습니다. 토요일 오후(15명) · 관람 1시간을 먼저 잡고 식사를 뒤에 붙인 형태 — **지킬 것 04를 이미 지키고 있습니다**"], ["10월", "**한두 번 온 사람**", "영화 또는 작은 공연장 · 토 늦은 오후 → 저녁", "이분들이 영화 4/9 · 음악회 5/9 · **토요일 저녁에 올 수 있는 유일한 무리(7/9)**. 자유서술에 「독립영화관」 「저렴한 뮤지컬·연극」이 직접 나왔습니다"], ["10월 따로", "작은 모임", "작은 미술관에 3~5명 · 토 낮", "큰 모임이 부담스러운 분들에게 맞는 크기 · 조를 섞는 연습 · 「소규모 갤러리」가 자유서술에 나왔습니다"], ["11월", "자주 오는 사람", "현대미술 · 미디어아트 · 토 낮", "현대미술과 사진·미디어아트가 **나란히 1위(각 9명·50%)** · 푹 빠져서 보기 좋은 형태"], ["아무 때나 한 번", "비용이 부담인 분", "무료 전시 또는 국립중앙박물관 + 용산공원", "회원이 가장 많이 추천한 곳(3명) · **무료** · 도심에서 가깝고 **관람 + 산책**(13명·72%)이 자연스럽게 붙습니다"], ["1년에 한 번", "가고 싶은 사람만", "경기 나들이 (용인 호암미술관 등)", "경기가 편하다는 분은 4명뿐 · 매달 일정에 넣지 말고 **따로 모을 것**"]]}, {"k": "note", "t": "날짜와 여는 기간은 **그 미술관 홈페이지에서 다시 확인하고** 정하세요. 자유서술에 나온 다른 곳 — 박서보미술관(2명) · 김환기미술관 · 구하우스 · 워커힐 빛의씨어터 · 아트하우스 모모 · 유영국 전 · 연희동 투어."}, {"k": "h", "n": "07", "t": "이번 주에 할 세 가지"}, {"k": "lede", "t": "돈도 회의도 필요 없고, 하루 안에 끝납니다. 셋 다 미루면 다음 달 설문도 똑같은 결과가 나옵니다."}, {"k": "rule", "kind": "yes", "n": "지금 바로 01", "t": "아직 답 안 한 3명에게 개인 메시지", "chg": null, "ps": ["지난달에 이걸 해서 **다섯 명이 셋으로 줄었습니다.** 그리고 새로 답한 한 분이 장벽을 셋이나 갖고 있었습니다. **남은 3명 중에도 있을 수 있습니다.** 단톡방 공지 말고 개인 메시지로요."], "quote": null, "ev": null}, {"k": "rule", "kind": "yes", "n": "지금 바로 02", "t": "일정 올릴 사람 한 명을 정해 단톡방에 알리기", "chg": null, "ps": ["이 한 문장이면 됩니다 — **「앞으로 일정은 ○○이 한 번만 올리고, 바뀌면 그 글을 고치겠습니다.」**"], "quote": null, "ev": null}, {"k": "rule", "kind": "yes", "n": "지금 바로 03", "t": "「보고 싶은 곳」을 받는 자리를 연다", "chg": null, "ps": ["9명(50%)이 하겠다고 했고, **그중 다수가 자주 안 나오는 분들**입니다. 가장 쉬운 참여 통로이니 여기부터 열면 나머지가 따라옵니다. 이미 이름이 나온 곳이 아홉 군데 있으니 **그것부터 목록으로 올리면 됩니다.**"], "quote": null, "ev": null}, {"k": "h", "n": "부록 A", "t": "문항별 전체 집계"}, {"k": "lede", "t": "22개 문항의 모든 보기를 뺀 것 없이 싣습니다. 비율은 전부 **18명 가운데 몇 명**인지입니다. 「여러 개 고름」 문항은 합이 100%를 넘습니다."}, {"k": "fold", "t": "문항 22개 전체 펼쳐보기", "blocks": [{"k": "bars", "t": "Q5 관심 분야", "kind": "여러 개 고름", "rows": [["미술 전시·갤러리", 13, 72], ["박물관·역사·궁궐", 10, 56], ["클래식·음악회·공연",